function openDB(): Promise<IDBDatabase>{ return new Promise((res,rej)=>{ const req=indexedDB.open('vibra-db',1); req.onupgradeneeded=()=>{ if(!req.result.objectStoreNames.contains('videos')) req.result.createObjectStore('videos',{keyPath:'id'}) }; req.onsuccess=()=>res(req.result); req.onerror=()=>rej(req.error) }) }
async function saveVideoDB(id:number, file:Blob, caption:string){ try{ const db=await openDB(); const tx=db.transaction('videos','readwrite'); tx.objectStore('videos').put({id, blob:file, caption}); await new Promise(r=>tx.oncomplete=r) }catch{} }
async function loadVideosDB(): Promise<Clip[]>{ try{ const db=await openDB(); const tx=db.transaction('videos','readonly'); const all:any[]=await new Promise((res,rej)=>{ const r=tx.objectStore('videos').getAll(); r.onsuccess=()=>res(r.result); r.onerror=()=>rej(r.error) }); return all.sort((a,b)=>b.id-a.id).map(v=>({id:v.id, url:URL.createObjectURL(v.blob), caption:v.caption})) }catch{ return [] } }
function renderCaption(text:string){ if(!text) return null; const parts=text.split(/(#[\wÀ-ÿ]+)/g); return <span>{parts.map((p,i)=> p.startsWith('#') ? <span key={i} style={vibraTextTeal}>{p} </span> : <span key={i} style={{color:'#fff'}}>{p}</span> )}</span> }
function VibraCamera({ onDone, onClose }: { onDone: (file: Blob, caption: string) => void, onClose: () => void }) {
  const videoRef = useRef<HTMLVideoElement>(null); const streamRef = useRef<MediaStream | null>(null); const recorderRef = useRef<MediaRecorder | null>(null); const chunksRef = useRef<Blob[]>([])
  const [isRecording, setIsRecording] = useState(false); const [facing, setFacing] = useState<'user' | 'environment'>('user'); const [beauty, setBeauty] = useState(true); const [effect, setEffect] = useState('beauty'); const [faceEffect, setFaceEffect] = useState('none'); const [caption, setCaption] = useState(''); const [recordedUrl, setRecordedUrl] = useState(''); const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null); const [timeLeft, setTimeLeft] = useState(0)
  const effects: Record<string, string> = { normal: 'none', beauty: 'brightness(1.15) contrast(1.1) saturate(1.2)', bw: 'grayscale(1) contrast(1.2)', warm: 'sepia(0.3) brightness(1.1)', cool: 'hue-rotate(180deg) saturate(1.2)', vivid: 'saturate(1.8) contrast(1.2)' }
  const startCamera = async (face: 'user' | 'environment') => { try { streamRef.current?.getTracks().forEach(t => t.stop()); const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: face }, audio: true }); streamRef.current = stream; if (videoRef.current) { videoRef.current.srcObject = stream; videoRef.current.play().catch(()=>{}) } } catch { alert('Ruhusu kamera: Allow') } }
  useEffect(() => { startCamera(facing); return () => streamRef.current?.getTracks().forEach(t => t.stop()) }, [])
  useEffect(() => { startCamera(facing) }, [facing])
  const doRecord = () => { if (isRecording) { recorderRef.current?.stop(); setIsRecording(false); return }; if (!streamRef.current) return; chunksRef.current = []; const rec = new MediaRecorder(streamRef.current, { mimeType: 'video/webm' }); recorderRef.current = rec; rec.ondataavailable = e => { if (e.data.size > 0) chunksRef.current.push(e.data) }; rec.onstop = () => { const blob = new Blob(chunksRef.current, { type: 'video/webm' }); setRecordedBlob(blob); setRecordedUrl(URL.createObjectURL(blob)) }; rec.start(); setIsRecording(true); setTimeLeft(15); const iv = setInterval(() => { setTimeLeft(v => { if (v <= 1) { clearInterval(iv); rec.stop(); setIsRecording(false); return 0 } return v - 1 }) }, 1000) }
  const useVideo = () => { if (!recordedBlob) return; let cap = caption.trim(); if (!cap) cap = '#Vibra #Mombasa'; else if (!cap.includes('#')) cap += ' #Vibra #Mombasa'; onDone(recordedBlob, cap) }
  const renderFace = () => { if (faceEffect === 'dog') return <div style={{fontSize:100}}>🐶</div>; if (faceEffect === 'glasses') return <div style={{fontSize:100}}>😎</div>; if (faceEffect === 'crown') return <div style={{fontSize:100}}>👑</div>; if (faceEffect === 'cat') return <div style={{fontSize:100}}>🐱</div>; if (faceEffect === 'fire') return <div style={{fontSize:100}}>🔥</div>; return null }
  return (<div style={{ position: 'fixed', inset: 0, zIndex: 1000, background: '#000', display: 'flex', flexDirection: 'column' }}><div style={{ display: 'flex', justifyContent: 'space-between', padding: '12px', color: '#fff' }}><button onClick={onClose} style={{ background: 'none', border: 'none', color: '#fff', fontSize: 24 }}>✕</button><div style={{display:'flex',gap:8}}><button onClick={() => setFacing(f => f === 'user' ? 'environment' : 'user')} style={{ background: GRADIENT_BTN, border: 'none', color: '#fff', width: 38, height: 38, borderRadius: '50%' }}>🔄</button><button onClick={() => { setBeauty(!beauty); setEffect(beauty ? 'normal' : 'beauty') }} style={{ background: GRADIENT_BTN, border: 'none', color: '#fff', width: 38, height: 38, borderRadius: '50%' }}>✨</button></div></div><div style={{ flex: 1, position: 'relative', background: '#111', overflow: 'hidden' }}>{!recordedUrl ? (<video ref={videoRef} autoPlay playsInline muted style={{ width: '100%', height: '100%', objectFit: 'cover', filter: effects[effect], transform: facing === 'user' ? 'scaleX(-1)' : 'none' }} />) : (<video src={recordedUrl} controls autoPlay loop style={{ width: '100%', height: '100%', objectFit: 'cover' }} />)}{faceEffect !== 'none' && !recordedUrl && (<div style={{ position: 'absolute', left: '50%', top: '48%', transform: 'translate(-50%, -50%)' }}>{renderFace()}</div>)}{isRecording && <div style={{ position: 'absolute', top: 10, left: '50%', transform: 'translateX(-50%)', background: GRADIENT_BTN, color: '#fff', padding: '6px 14px', borderRadius: 20, fontWeight: 'bold' }}>🔴 {timeLeft}s</div>}</div>{!recordedUrl && (<><div style={{ display: 'flex', gap: 8, overflowX: 'auto', padding: '10px', background: '#000' }}>{[['normal','Normal'],['beauty','Beauty ✨'],['bw','B&W'],['warm','Warm ☀️'],['cool','Cool ❄️'],['vivid','Vivid 🌈']].map(([key,label]) => (<button key={key} onClick={() => setEffect(key)} style={{ background: effect === key ? GRADIENT_BTN : '#222', color: '#fff', border: 'none', padding: '8px 14px', borderRadius: 20, whiteSpace: 'nowrap' }}>{label}</button>))}</div><div style={{ display: 'flex', gap: 8, overflowX: 'auto', padding: '4px 12px', background: '#000' }}>{[['none','❌ Hakuna'],['dog','🐶 Mbwa'],['cat','🐱 Paka'],['glasses','😎 Miwani'],['crown','👑 Taji'],['fire','🔥 Moto']].map(([key,label]) => (<button key={key} onClick={() => setFaceEffect(key)} style={{ background: faceEffect === key ? GRADIENT_BTN : '#333', color: '#fff', border: 'none', padding: '8px 14px', borderRadius: 20, whiteSpace: 'nowrap' }}>{label}</button>))}</div></>)}{recordedUrl && (<div style={{ padding: '12px', background: '#000' }}><input value={caption} onChange={e => setCaption(e.target.value)} placeholder="Caption... #Vibra #Mombasa" style={{ width: '100%', padding: 12, borderRadius: 12, border: `2px solid ${TEAL}`, background: '#111', color: '#fff' }} /><div style={{ display: 'flex', gap: 10, marginTop: 12 }}><button onClick={() => { setRecordedUrl(''); setRecordedBlob(null) }} style={{ flex: 1, padding: 14, borderRadius: 12, background: '#333', color: '#fff', border: 'none', fontWeight: 'bold' }}>🔄 Rekodi Tena</button><button onClick={useVideo} style={{ flex: 2, padding: 14, borderRadius: 12, background: GRADIENT_BTN, color: '#fff', border: 'none', fontWeight: 'bold' }}>✅ Tumia Video Hii</button></div></div>)}{!recordedUrl && (<div style={{ padding: '14px', background: '#000', display:'flex', alignItems:'center', justifyContent:'space-between' }}><span style={vibraText}>✨ Effects</span><button onClick={doRecord} style={{ width: 72, height: 72, borderRadius: '50%', background: GRADIENT_BTN, border: `4px solid ${TEAL}`, color: '#fff', fontSize: 14, fontWeight: 'bold' }}>{isRecording ? '⏹️' : '🔴'}</button><label style={vibraText}>📁 Upload<input type="file" accept="video/*" style={{ display: 'none' }} onChange={e => { const f = e.target.files?.[0]; if (f) onDone(f, '#Vibra #Mombasa') }} /></label></div>)}</div>)
}
